function costSheet(c){modal('<h2 style="margin-top:0">Purchase price</h2><div class="row" style="align-items:flex-start"><div style="width:90px">'+slab(c,{k:'m'})+'</div><div class="sp"><b>'+esc(c.player)+'</b><div class="sm mut">'+esc(c.set+' · '+c.grader+' '+c.grade)+'</div><div class="sm" style="margin-top:6px">Market value <b>'+vtxt(c)+'</b></div></div></div>'+
  '<label class="f" for="cCost">What did you pay?</label><input id="cCost" type="number" inputmode="decimal" placeholder="$" value="'+(c.cost!=null?c.cost:'')+'"><label class="f" for="cDate">Purchase date</label><input id="cDate" type="date" max="'+TODAY+'" value="'+(c.costDate||TODAY)+'">'+
  '<div class="setrow"><div><b>Keep purchase price private</b><div class="sm mut">Hidden from your public profile &amp; showcase. Always visible to you.'+(S.settings.hideAllCosts?' (Currently hidden globally.)':'')+'</div></div><label class="toggle"><input type="checkbox" id="cPriv"'+(c.hideCost?' checked':'')+' aria-label="Keep private"><span></span></label></div>'+
  '<div class="row" style="margin-top:8px"><button class="btn pri" data-act="saveCost" data-id="'+c.id+'">Save</button>'+(c.cost!=null?'<button class="btn ghost" data-act="clearCost" data-id="'+c.id+'">Clear</button>':'')+'</div><div class="panel" style="margin-top:14px">'+compsTable(c)+'</div>')}
var pendingAdd=null;
