function fakeLookup(g,cert,sp){var pool=sp?D.catalog.filter(function(x){return x.sport===sp}):D.catalog;if(!pool.length)pool=D.catalog;var cat=pool[hash(g+cert)%pool.length],r=rng(cert);var gr=g==='BGS'?['9','9.5','10'][Math.floor(r()*3)]:['8','9','10'][Math.floor(r()*3)];var m={'8':.35,'9':.6,'9.5':.85,'10':1}[gr];var fair=Math.round(cat.base*m*(.9+r()*.2));
  var comps=[];for(var i=0;i<6;i++){var d=new Date('2026-10-17T12:00:00');d.setDate(d.getDate()-Math.floor(r()*80));var alt=r()<.25;comps.push({date:d.toISOString().slice(0,10),source:alt?'Alt':'eBay sold',type:alt?'Alt Marketplace':'Auction',price:Math.round(fair*(.87+r()*.26))})}comps.sort(function(a,b){return b.date.localeCompare(a.date)});
  return {id:uid('M'),sport:cat.sport,player:cat.player,set:cat.set,num:cat.num,variant:cat.sport==='Pokemon'?'Holo':'Base',grader:g,grade:gr,cert:cert,pop:Math.floor(r()*3000)+20,comps:comps,owner:'you',mode:'none',price:fair,hue:Math.floor(r()*360),listed:TODAY,views:0,hideCost:true,cost:null,costDate:null}}

