function trk(){return '1Z9DEMO'+Math.floor(1e4+Math.random()*9e4)}
function respond(id){setTimeout(function(){var t=findT(id);if(!t)return;var o=other(t);if(t.turn!==o||['pending','countered'].indexOf(t.status)<0)return;var s=sides(t),l=sumV(s.myCards)+s.myCash,r=sumV(s.theirCards)+s.theirCash;
    if(l>=r*.94){t.status='accepted';t.turn=null;t.step=0;t.track={a:trk(),b:trk()};t.events.push({ts:Date.now(),t:'@'+o+' accepted — prepaid insured labels sent'});notify('@'+o+' accepted your offer '+t.id+' 🎉','#/trade/'+t.id)}
    else{var gap=Math.max(5,Math.round((r-l)/5)*5);if(t.a==='you')t.aCash+=gap;else t.bCash+=gap;t.status='countered';t.turn='you';t.events.push({ts:Date.now(),t:'@'+o+' countered: asked for '+money(gap)+' more cash'});notify('@'+o+' sent a counteroffer on '+t.id,'#/trade/'+t.id);(S.msgs[o]=S.msgs[o]||[]).push({me:0,t:'Close! Add '+money(gap)+' and it’s a deal?',ts:Date.now()});S.unreadMsg[o]=1}
    save();rerenderIf(/^#\/(trade\/|trades|notifications|messages)/)},3500)}
