/* ---------- real portfolio, reference-style tiles, buy/offer ---------- */
var SPORTS=['All','Basketball','Football','Baseball','Hockey','Soccer','Formula 1','Wrestling','Garbage Pail Kids','Pokemon'];
function slabBadges(c){var b=[];if(c.rc||/Rookie|\bRC\b/.test(c.num+' '+(c.variant||'')))b.push('<span class="bdg rc" title="Rookie card">RC</span>');if(c.pop&&c.pop<=100)b.push('<span class="bdg pop" title="PSA population at this grade">POP<b>'+c.pop+'</b></span>');if(/\/\s?\d+/.test(c.variant||''))b.push('<span class="bdg ser" title="Serial numbered">#<b>'+esc((c.variant.match(/\/\s?\d+/)||[''])[0])+'</b></span>');return b.length?'<div class="bdgs">'+b.join('')+'</div>':'<div class="bdgs"></div>'}
function cleanNum(c){return String(c.num||'').replace(/\s*Rookie$/,'')}
function gradeLine(c){return (c.grader||c.grade)?(c.grader+' '+c.grade).trim():'Grade needed'}
function titleLine(c){return esc(c.set+((c.variant&&c.variant!=='Base')?' '+c.variant:''))}
function priceFor(c){if(c.owner==='you')return c.nfs?null:(c.listPrice||null);return (c.mode==='sale'||c.mode==='both')?c.price:null}
function btnLabel(c){if(c.owner==='you'){if(c.nfs)return null;return (c.listPrice||c.offers)?'BUY / OFFER':null}return c.mode&&c.mode!=='none'?'BUY / OFFER':null}
function rtile(c,o){o=o||{};var saved=S.saved.indexOf(c.id)>=0,pr=priceFor(c),bl=o.owner?null:btnLabel(c),v=value(c);
  var big=pr!=null?money(pr):(c.real?compFig(c):(v!=null?money(v):'<span class="pend">Value pending</span>'));
  var sub=pr!=null&&v!=null&&c.owner==='you'?'<div class="sm mut2">Market '+money(v)+'</div>':(pr==null&&v!=null&&!c.real?'<div class="sm mut2">Market value</div>':'');
  return '<div class="rtile" style="animation-delay:'+Math.min(o.i||0,20)*25+'ms">'+(c.owner==='you'?ofTog(c):'')+'<a class="rt-img" href="#/card/'+c.id+(o.preview?'?as=buyer':'')+'">'+slab(c,{k:o.k||'r'})+slabBadges(c)+sampleCap(c)+rpBtn(c)+'</a>'+
   (c.owner!=='you'?'<button class="rt-heart'+(saved?' on':'')+'" data-act="save" data-id="'+c.id+'" aria-label="Save to wishlist"><svg viewBox="0 0 24 24"><path d="M12 21s-8-5.2-8-11a4.5 4.5 0 0 1 8-2.8A4.5 4.5 0 0 1 20 10c0 5.8-8 11-8 11z"/></svg></button>':'')+
   '<a class="rt-info" href="#/card/'+c.id+(o.preview?'?as=buyer':'')+'"><div class="rt-t">'+titleLine(c)+'</div><div class="rt-t">'+esc(c.player)+' '+esc(cleanNum(c))+'</div><div class="rt-g">'+gradeLine(c)+(c.demo?' <span class="demo-chip">demo</span>':'')+'</div>'+(c.owner!=='you'&&!o.nofv?'<div style="margin-top:4px">'+fvBadge(c)+'</div>':'')+'</a>'+
   '<div class="rt-foot"><div><div class="rt-price">'+big+'</div>'+sub+'</div>'+(bl?'<button class="rt-btn" data-act="buyOffer" data-id="'+c.id+'"'+(o.preview?' data-preview="1"':'')+'>'+bl+'</button>'+cartBtn(c):(o.owner?'':'<span class="sm mut2">'+(c.owner==='you'&&c.nfs?'Not for sale':'')+'</span>'))+'</div>'+(o.extra||'')+'</div>'}
function tile(c,o){return rtile(c,o)}
function gridHtml(L){return L.length?L.map(function(c,i){return tile(c,{i:i})}).join(''):'<div class="empty">No slabs match. Try widening filters — or save this search to get alerted.</div>'}
function altBlock(c,full){var s=altSales(c),v=value(c),cc=COMPS.cards[c.cert]||{},url=cc.url||cc.altUrl,asOf=altAsOf(c),srcs=s.map(function(x){return (x.source||'Alt').replace(/ \(eBay\)/,'')}).filter(function(x,i,a){return a.indexOf(x)===i}).join(' + ');
  return '<div class="mkt"><div class="row"><span class="mkt-l">Market (Comps avg)</span><span class="sp"></span>'+compFig(c,'mkt-v')+'</div>'+
   (s.length?'<table class="mini"><thead><tr><th>Date</th><th class="n">Price</th><th>Source</th></tr></thead><tbody>'+s.map(function(x){return '<tr><td data-v="'+x.date+'">'+fmtDate(x.date)+'</td><td class="n" data-v="'+x.price+'">'+money(x.price,1)+'</td><td class="sm">'+esc(x.source||'Alt')+'</td></tr>'}).join('')+'</tbody></table>':'<div class="sm mut2" style="margin:4px 0">No recent sales recorded for this card and grade yet.</div>')+
   '<div class="sm mut2">'+(asOf?'As of '+fmtDate(asOf):'Not yet looked up')+' · source: '+esc(srcs||'—')+(url&&full?' · <a href="'+esc(url)+'" target="_blank" rel="noopener">'+esc((cc.urlLabel||'View source').toLowerCase())+' ↗</a>':'')+'</div></div>'}
function pcard(c,i){var v=value(c),g=(c.cost!=null&&v!=null)?v-c.cost:null;
  return '<div class="rtile pc" style="animation-delay:'+i*40+'ms"><a class="rt-img" href="#/card/'+c.id+'">'+slab(c,{k:'pc'})+slabBadges(c)+'</a>'+
  '<div class="rt-info"><div class="rt-t">'+titleLine(c)+qtyBadge(c)+'</div><div class="rt-t">'+esc(c.player)+' '+esc(cleanNum(c))+'</div><div class="rt-g">'+esc(c.gradeLabel?c.grader+' '+c.gradeLabel:gradeLine(c))+'</div>'+
  '<div class="sm mut2" style="margin-top:3px">'+(c.cert?'Cert <a href="https://www.psacard.com/cert/'+esc(c.cert)+'" target="_blank" rel="noopener">'+esc(c.cert)+' ↗</a> · ':'')+ebayLine(c)+(c.detailsNeeded?'<span class="warn">Details needed: grade/cert/full title</span>':c.psaVerified?'<span class="ok">PSA verified ✓</span>':(c.real?'<span class="warn">Verify on PSA</span>':'Demo card'))+'</div></div>'+
  '<div class="pc-bottom">'+(c.real?altBlock(c,true):'<div class="mkt"><div class="row"><span class="mkt-l">Market (comps median)</span><span class="sp"></span><b class="mkt-v">'+vtxt(c)+'</b></div></div>')+
  '<label class="paid"><span>Paid $</span><input type="number" inputmode="decimal" min="0" step="0.01" data-paid="'+c.id+'" value="'+(c.cost!=null?c.cost:'')+'" placeholder="Enter what you paid" aria-label="Paid for '+esc(c.player)+'"><span class="lock" title="Private — only you see this">🔒 Private</span></label>'+paidNote(c)+
  (g!=null?'<div class="sm" style="margin-top:6px">Gain/loss <b class="'+(g>=0?'pos2':'neg2')+'">'+(g>=0?'+':'−')+money(Math.abs(g),1)+' ('+pct(g/c.cost*100)+')</b></div>':'')+
  '<div class="ofrow"><button class="btn sm lt" data-act="sellSet" data-id="'+c.id+'">Sell settings</button><span class="sp"></span><span class="ofdiv"></span><span class="ofgrp"><span class="ofl'+(ofOpen(c)?'':' off')+'">'+(ofOpen(c)?'Open to Offers':'Not for offers')+'</span><span class="oftog-in">'+ofTog(c)+'</span></span></div>'+ofPriceLine(c)+'</div></div>'}
function ofPriceLine(c){var v=value(c),ask=c.listPrice;if(!ofOpen(c))return '<div class="ofpl off">Hidden from buyers</div>';return '<div class="ofpl"><button class="ofprice" data-act="ofEdit" data-id="'+c.id+'" title="Click to raise asking price">'+(ask?money(ask)+' <span class="oftag">Asking</span>':(v!=null?money(v)+' <span class="oftag c">Comp</span>':'Set price'))+'</button></div>'}
function totals(){var t_ac=0,L=S.mine,paid=0,mk=0,pc=0,mc=0,bpaid=0,bmk=0;L.forEach(function(c){var v=value(c);if(c.cost!=null){paid+=c.cost;pc++}var atc=0;if(v!=null){mk+=v;mc++}else if(c.cost!=null){mk+=c.cost;t_ac++}if(c.cost!=null){bpaid+=c.cost;bmk+=(v!=null?v:c.cost)}});return {paid:paid,mk:mk,pc:pc,mc:mc,ac:t_ac,g:bmk-bpaid,base:bpaid,n:L.length}}
function totalsHtml(){var t=totals(),M=function(x){return view.mask?'<span style="filter:blur(6px)">'+x+'</span>':x};
  return '<div class="stat"><span>Paid</span><b>'+M(money(t.paid,1))+'</b><span class="sm">'+t.pc+' of '+t.n+' cards entered</span></div><div class="stat"><span>Market</span><b>'+M(money(t.mk,1))+'</b><span class="sm">'+t.mc+' of '+t.n+' valued · comps avg'+(t.ac?' · '+t.ac+' at cost (comps pending)':'')+'</span></div><div class="stat"><span>Gain / loss</span><b class="'+(t.g>=0?'pos':'neg')+'">'+(t.base?M((t.g>=0?'+':'−')+money(Math.abs(t.g),1)):'—')+'</b><span class="sm">cards without comps counted at cost</span></div><div class="stat"><span>Return</span><b class="'+(t.g>=0?'pos':'neg')+'">'+(t.base?pct(t.g/t.base*100):'—')+'</b></div>'}
function ptableHtml(){var M=function(x){return view.mask?'<span style="filter:blur(6px)">'+x+'</span>':x},t=totals();
  return '<table id="ptable"><thead><tr><th>Card</th><th>Grade</th><th>Cert</th><th class="n">Paid</th><th class="n">Market</th><th class="n">Gain $</th><th class="n">Gain %</th><th class="n">Comps</th></tr></thead><tbody>'+S.mine.map(function(c){var v=value(c),g=(c.cost!=null&&v!=null)?v-c.cost:null;return '<tr data-href="#/card/'+c.id+'" style="cursor:pointer"><td data-v="'+esc(c.player)+'"><b>'+esc(c.player)+'</b><div class="sm mut">'+esc(c.set)+'</div></td><td>'+gradeLine(c)+'</td><td>'+(c.cert?esc(c.cert):'<span class="pill y">Needed</span>')+'</td><td class="n" data-v="'+(c.cost==null?'':c.cost)+'">'+(c.cost!=null?M(money(c.cost,1)):'—')+'</td><td class="n" data-v="'+(v==null?'':v)+'">'+(v!=null?M(money(v,1)):'<span class="pill y">Comps pending</span>')+'</td><td class="n '+(g>=0?'pos':'neg')+'" data-v="'+(g==null?'':g)+'">'+(g==null?'—':M((g>=0?'+':'−')+money(Math.abs(g),1)))+'</td><td class="n '+(g>=0?'pos':'neg')+'" data-v="'+(g==null?'':(g/c.cost*100).toFixed(2))+'">'+(g==null?'—':pct(g/c.cost*100))+'</td><td class="n" data-v="'+(c.real?altSales(c).length:c.comps.length)+'">'+(c.real?altSales(c).length:c.comps.length)+'</td></tr>'}).join('')+
  '<tr class="total"><td>TOTAL</td><td>'+t.n+' slabs</td><td></td><td class="n">'+M(money(t.paid,1))+'</td><td class="n">'+M(money(t.mk,1))+'</td><td class="n '+(t.g>=0?'pos':'neg')+'">'+(t.base?M((t.g>=0?'+':'−')+money(Math.abs(t.g),1)):'—')+'</td><td class="n '+(t.g>=0?'pos':'neg')+'">'+(t.base?pct(t.g/t.base*100):'—')+'</td><td></td></tr></tbody></table>'}
function vPortfolio(){return '<div class="fadein"><div class="row"><div><h1>My portfolio</h1>'+pubToggle()+'<p class="sub">Your PSA slabs. What you paid is private — visitors never see it. Market = comps avg: the 5 most recent sold sales (Alt, Fanatics Collect, eBay via SportsCardsPro). Tap a value to see each sale and its source.</p></div><span class="sp"></span><div class="row"><button class="btn sm" data-act="scanOpen">📷 Scan to add</button><button class="btn sm" data-act="addSlab">＋ Add by cert #</button><button class="btn sm ghost" data-act="mask">'+(view.mask?'👁 Show':'🙈 Hide')+' amounts</button></div></div>'+
  '<div class="statgrid" id="ptotals">'+totalsHtml()+'</div>'+vchartPanel('vc_port',portWeekly(),'Portfolio value')+''+importPanel()+'<div class="rgrid pgrid" style="margin-top:14px">'+S.mine.map(pcard).join('')+'</div>'+
  '<div class="panel" style="margin-top:16px"><div class="row"><h3 style="margin:0">Holdings</h3><span class="sp"></span><span class="sm mut">Tap headers to sort</span></div><div class="tablewrap" id="ptablewrap">'+ptableHtml()+'</div></div></div>'}
function vShowcase(){var pub=view.pub,L=S.mine;
  return '<div class="fadein"><div class="row"><div><h1>My showcase</h1><p class="sub">'+L.length+' slabs · this is your public collection page.</p></div><span class="sp"></span><div class="row"><button class="btn" data-act="scanOpen">📷 Scan to add</button><button class="btn pri" data-act="addSlab">＋ Add by cert #</button></div></div>'+
  '<div class="row" style="margin-bottom:12px"><div class="tabs" style="margin:0"><button class="'+(!pub?'on':'')+'" data-act="pubView" data-v="0">Owner view</button><button class="'+(pub?'on':'')+'" data-act="pubView" data-v="1">Preview as public</button></div><span class="sp"></span><a href="#/portfolio" class="btn sm ghost">Portfolio ›</a></div>'+
  (pub?'<p class="note">This is exactly what visitors see: market value (or your list price) and a Buy / Offer button. What you paid is never shown.</p>':'')+
  '<div class="rgrid">'+L.map(function(c,i){return rtile(c,{i:i,k:'sc',preview:pub,owner:!pub,extra:pub?'':'<div class="row rt-own"><button class="btn sm lt" data-act="sellSet" data-id="'+c.id+'">Sell settings</button><span class="sm mut2">'+(c.nfs?'Not for sale':c.listPrice?'Buy now '+money(c.listPrice):c.offers?'Open to offers':'Hidden button')+'</span></div>'})}).join('')+'</div></div>'}
function vProfile(h){var html=vProfileOld(h),me=h==='you';var cards=me?S.mine:D.listings.filter(function(c){return c.owner===h&&!S.gone[c.id]});
  var g='<div class="rgrid">'+cards.map(function(c,i){return rtile(c,{i:i,k:'pf',preview:me})}).join('')+'</div>';
  return html.replace(/<div class="grid">[\s\S]*?<\/div><h2>Recent reviews/,g+'<h2>Recent reviews')}
function vCard(id){var c=card(id);if(!c||!c.real)return vCardBase(id);var v=value(c),pr=priceFor(c);
  return '<div class="fadein"><a href="#/portfolio" class="backbtn">← Back to Portfolio</a><div class="detail" style="margin-top:8px"><div><div class="rt-img big">'+slab(c,{k:'d'})+slabBadges(c)+sampleCap(c)+'</div><div class="row" style="gap:8px;flex-wrap:wrap">'+(c.imgBack?'<button class="rpbtn big flipbtn" data-act="flip" data-id="'+c.id+'">↻ Show back</button>':'')+rpBtn(c,1)+'</div></div><div><div class="row"><span class="pill">'+esc(c.sport)+'</span><span class="pill">'+gradeLine(c)+'</span>'+(c.detailsNeeded?'<span class="pill y">Details needed: grade/cert/full title</span>':c.psaVerified?'<span class="pill g">PSA verified ✓</span>':'<span class="pill y">Verify on PSA</span>')+'</div>'+
  '<h1 style="margin-top:8px">'+esc(c.player)+' '+esc(cleanNum(c))+'</h1><p class="sub">'+titleLine(c)+'</p><div class="kv"><div><span>Grade</span><b>'+((c.grader||c.grade)?esc(c.grader+' '+(c.gradeLabel||c.grade)):'<span class="warn">Needed</span>')+'</b></div><div><span>Cert #</span><b>'+(c.cert?'<a href="https://www.psacard.com/cert/'+esc(c.cert)+'" target="_blank" rel="noopener">'+esc(c.cert)+' ↗</a>':'<span class="warn">Needed</span>')+'</b></div>'+(c.ebayItem?'<div><span>Bought on eBay</span><b><a href="'+esc(c.ebayUrl)+'" target="_blank" rel="noopener">#'+esc(c.ebayItem)+' ↗</a></b></div>':'')+'<div><span>Market (comps avg)</span><b>'+compFig(c)+'</b></div><div><span>'+(pr?'Your list price':'Listing')+'</span><b>'+(pr?money(pr):c.nfs?'Not for sale':c.offers?'Open to offers':'Not listed')+'</b></div></div>'+
  '<div class="panel" style="margin-top:12px">'+altBlock(c,true)+'</div>'+vchartPanel('vc_'+c.id,cardWeekly(c),'Value since purchase')+'<div class="panel" style="margin-top:12px"><label class="paid dark"><span>Paid $</span><input type="number" inputmode="decimal" min="0" step="0.01" data-paid="'+c.id+'" value="'+(c.cost!=null?c.cost:'')+'" placeholder="Enter what you paid"><span class="lock">🔒 Private</span></label>'+paidNote(c)+(c.detailsNeeded?'<div class="sm warn" style="margin-top:6px">Details needed: grade/cert/full title'+(c.ebayTitle?' · eBay title: “'+esc(c.ebayTitle)+'”':'')+'</div>':'')+'<div class="row" style="margin-top:10px"><button class="btn sm" data-act="sellSet" data-id="'+c.id+'">Sell settings</button><a class="btn sm ghost" href="#/portfolio?pub=1">See public view</a></div></div></div></div></div>'}
function sellSheet(c){modal('<h2 style="margin-top:0">Sell settings</h2><p class="sub">'+esc(c.player+' · '+gradeLine(c))+' · market '+vtxt(c)+'</p><div class="setrow"><div><b>Not for sale</b><div class="sm mut">Hides the Buy / Offer button for visitors</div></div><label class="toggle"><input type="checkbox" id="sNfs"'+(c.nfs?' checked':'')+'><span></span></label></div><label class="f" for="sList">List price (shows BUY NOW)</label><input id="sList" type="number" inputmode="decimal" placeholder="Leave empty for offers only" value="'+(c.listPrice||'')+'"><div class="setrow"><div><b>Open to offers</b><div class="sm mut">Visitors can send cash and/or card offers</div></div><label class="toggle"><input type="checkbox" id="sOff"'+(c.offers?' checked':'')+'><span></span></label></div><label class="f" for="sPh">Upload slab photos (front/back)</label><input id="sPh" type="file" accept="image/*" multiple onchange="rpUp(this,\''+c.id+'\')"><div class="sm mut" id="sPhN" style="margin-bottom:12px">'+((c.photos||[]).length?(c.photos.length+' photo(s) attached'):'Buyers see these via the 📷 Real photos button')+'</div>'+tradeCatPicker(c)+'<button class="btn pri block" data-act="saveSell" data-id="'+c.id+'">Save</button>')}
function buySheet(c,preview){var pr=priceFor(c),v=value(c),open=c.owner==='you'?c.offers:true;
  modal('<h2 style="margin-top:0">'+(pr?'Buy or make an offer':'Make an offer')+(preview?' <span class="pill y">Preview</span>':'')+'</h2>'+(preview?'<p class="note">You’re previewing your own card as a visitor. Nothing will be sent.</p>':'')+
  '<div class="row" style="align-items:flex-start"><div style="width:96px">'+slab(c,{k:'bo'})+'</div><div class="sp"><b>'+esc(c.player)+' '+esc(cleanNum(c))+'</b><div class="sm mut">'+titleLine(c)+'</div><div class="sm"><b>'+gradeLine(c)+'</b> · cert '+esc(c.cert)+'</div><div class="sm" style="margin-top:4px">Market '+(v!=null?money(v,1):'pending')+(pr?' · Buy now <b>'+money(pr)+'</b>':'')+'</div></div></div>'+
  qtyStep(c)+'<button class="btn ghost block" style="margin-top:12px" data-act="cartAdd" data-id="'+c.id+'">'+(inCart(c.id)?'✓ In offer cart — view cart':'＋ Add to multi-card offer cart')+'</button>'+(pr?'<button class="btn pri block" style="margin-top:12px" data-act="boBuy" data-id="'+c.id+'"'+(preview?' data-preview="1"':'')+'>Buy now for '+money(pr)+'</button>':'')+
  (open?'<h3 style="margin-top:16px">Offer</h3><label class="f" for="boAmt">Cash offer</label><input id="boAmt" type="number" inputmode="numeric" value="'+Math.round((pr||v||100)*.92)+'"><label class="f">Add cards from your showcase (optional)</label><div class="pick">'+(preview?D.listings.slice(0,4):S.mine.filter(function(m){return m.id!==c.id})).map(function(m){return '<div class="p" data-act="boPick" data-id="'+m.id+'">'+slab(m,{k:'bp'})+'<div class="pv">'+vtxt(m)+'</div></div>'}).join('')+'</div><button class="btn blue block" style="margin-top:12px" data-act="boSend" data-id="'+c.id+'"'+(preview?' data-preview="1"':'')+'>Send offer</button>':'')+
  '<p class="note">Demo — no payment is taken. Trades and purchases run through the insured hub.</p>')}
A.buyOffer=function(d,e,ev){ev.preventDefault();ev.stopPropagation();buySheet(card(d.id),!!d.preview||card(d.id).owner==='you')};
A.cpop=function(d,e,ev){if(ev.target.closest('a'))return;ev.preventDefault();ev.stopPropagation();var on=e.classList.contains('open');document.querySelectorAll('.cfig.open').forEach(function(x){x.classList.remove('open')});if(!on)e.classList.add('open')};
A.boPick=function(d,e){e.classList.toggle('on')};
A.boBuy=function(d){if(d.preview){toast('Preview only — visitors would check out here');return}A.buy(d)};
A.boSend=function(d){if(d.preview){toast('Preview only — visitors would send this offer to you');closeModal();return}var c=card(d.id),amt=Math.max(0,+$('#boAmt').value||0),cards=[].slice.call(document.querySelectorAll('#modal .pick .p.on')).map(function(x){return x.dataset.id});if(!amt&&!cards.length){toast('Add cash or a card');return}closeModal();
  var t={id:newTradeId(),a:'you',b:c.owner,aCards:cards,bCards:[c.id],aCash:amt,bCash:0,status:'pending',turn:c.owner,step:0,created:Date.now(),events:[{ts:Date.now(),t:(cards.length?'Offer with '+cards.length+' card'+(cards.length>1?'s':'')+' + ':'Cash offer of ')+money(amt)+' sent'}],kind:cards.length?'trade':'offer'};toast('Offer sent');respond(t.id);goTrade(t)};
A.sellSet=function(d,e,ev){if(ev)ev.preventDefault();sellSheet(card(d.id))};
A.saveSell=function(d){var c=card(d.id);c.tradeCats=[].slice.call(document.querySelectorAll('.tcat:checked')).map(function(x){return x.value});c.nfs=$('#sNfs').checked;var lp=parseFloat($('#sList').value);c.listPrice=isNaN(lp)||lp<=0?null:lp;c.offers=$('#sOff').checked;c.mode=c.nfs?'none':(c.listPrice?(c.offers?'both':'sale'):(c.offers?'trade':'none'));c.price=c.listPrice;save();closeModal();toast('Sell settings saved');render(true)};
function savePaid(t){var c=card(t.dataset.paid);if(!c)return;c.demoCost=false;var v=parseFloat(t.value);var nv=isNaN(v)||v<0?null:Math.round(v*100)/100;if(nv===c.cost)return;c.cost=nv;c.costDate=nv==null?null:(c.costDate||TODAY);c.hideCost=true;save();var a=$('#ptotals');if(a)a.innerHTML=totalsHtml();var b=$('#ptablewrap');if(b)b.innerHTML=ptableHtml();toast(nv==null?'Paid price cleared':'Saved privately — '+money(nv,1))}
document.addEventListener('focusout',function(ev){var t=ev.target;if(t.dataset&&t.dataset.paid)savePaid(t)});
document.addEventListener('keydown',function(ev){var t=ev.target;if(ev.key==='Enter'&&t.dataset&&t.dataset.paid){t.blur()}});

/* ---------- scan to add (demo: real file/camera + in-browser frame extraction; label reading simulated) ---------- */
var SC=null;
function scanOpen(){SC={items:[],busy:'',results:null,dupes:0,priv:true,date:TODAY};scanRender()}
function scanStep1(){var n=SC.items.length;
  return '<h2 style="margin-top:0">Scan to add <span class="pill y">Demo</span></h2><p class="sub">Take photos or a quick video panning across your slabs — labels facing the camera. We read each label and load the whole stack at once.</p>'+
  '<div class="row"><label class="btn pri" style="cursor:pointer">📷 Take photo / video<input type="file" id="scanCam" accept="image/*,video/*" capture="environment" hidden></label><label class="btn" style="cursor:pointer">🖼 Upload photos or video<input type="file" id="scanFiles" accept="image/*,video/*" multiple hidden></label></div>'+
  '<div class="row" style="margin-top:10px"><label class="sm mut" for="scanCat">Category</label><select id="scanCat"><option value="">Auto-detect</option>'+SPORTS.slice(1).map(function(x){return '<option'+(SC.cat===x?' selected':'')+'>'+x+'</option>'}).join('')+'</select></div>'+'<div id="scanBusy" class="sm mut" style="margin-top:10px">'+(SC.busy?'<span class="spinner"></span> '+esc(SC.busy):'')+'</div>'+
  (n?'<div class="row" style="margin-top:6px"><b>'+n+' image'+(n>1?'s':'')+' ready</b><span class="sm mut">'+SC.items.filter(function(i){return i.kind==='frame'}).length+' from video</span><span class="sp"></span><button class="btn sm ghost" data-act="scanClear">Clear</button></div>':'')+
  '<div class="scan-thumbs" id="scanThumbs">'+SC.items.map(function(it){return '<figure><img src="'+it.thumb+'" alt="'+esc(it.name)+'"><figcaption>'+(it.kind==='frame'?'🎞 '+esc(it.label):esc(it.name))+'</figcaption></figure>'}).join('')+'</div>'+
  '<button class="btn pri block" style="margin-top:14px" data-act="scanRead"'+(n&&!SC.busy?'':' disabled')+'>Read labels'+(n?' ('+n+')':'')+'</button>'+
  '<p class="note">Demo: your photos and video stay in this browser. Frames are really extracted from video, but label reading is simulated and returns sample matches.</p>'}
function confPill(c){var p=Math.round(c*100);return '<span class="pill '+(c>=.9?'g':c>=.8?'b':'y')+'">'+(c>=1?'Edited ✓':p+'%'+(c<.8?' · check':''))+'</span>'}
function scanStep2(){var R=SC.results,inc=R.filter(function(r){return r.inc}).length,low=R.filter(function(r){return r.conf<.8}).length;
  var rows=R.map(function(r,i){var c=r.card;return '<tr><td><input type="checkbox" data-scan="inc" data-i="'+i+'"'+(r.inc?' checked':'')+' aria-label="Include"></td><td><img class="scan-mini" src="'+r.thumb+'" alt=""></td>'+
   '<td data-v="'+esc(c.player)+'"><b>'+esc(c.player)+'</b><div class="sm mut">'+esc(c.set+' '+c.num)+'</div>'+(r.dupe?'<div class="sm" style="color:var(--warn)">Already in your showcase</div>':'')+(r.seen>1?'<div class="sm mut">Seen in '+r.seen+' frames/photos</div>':'')+'</td>'+
   '<td data-v="'+c.grader+'"><select data-scan="grader" data-i="'+i+'" aria-label="Grader">'+['PSA','BGS','SGC','CGC','CSG'].map(function(g){return '<option'+(g===c.grader?' selected':'')+'>'+g+'</option>'}).join('')+'</select></td>'+
   '<td data-v="'+c.cert+'"><input data-scan="cert" data-i="'+i+'" value="'+esc(c.cert)+'" inputmode="numeric" style="width:110px" aria-label="Cert number"></td>'+
   '<td data-v="'+c.grade+'"><select data-scan="grade" data-i="'+i+'" aria-label="Grade">'+['7','8','8.5','9','9.5','10'].map(function(g){return '<option'+(g===c.grade?' selected':'')+'>'+g+'</option>'}).join('')+'</select></td>'+
   '<td data-v="'+r.conf.toFixed(3)+'">'+confPill(r.conf)+'</td><td class="n" data-v="'+value(c)+'">'+vtxt(c)+'</td>'+
   '<td data-v="'+(r.cost||'')+'"><input data-scan="cost" data-i="'+i+'" type="number" inputmode="decimal" placeholder="$ optional" value="'+(r.cost||'')+'" style="width:105px" aria-label="Purchase price"></td>'+
   '<td><button class="btn sm bad" data-act="scanRemove" data-i="'+i+'" aria-label="Remove">✕</button></td></tr>'}).join('');
  return '<h2 style="margin-top:0">Review scanned slabs <span class="pill y">Demo</span></h2><p class="sub">Found <b>'+R.length+'</b> unique slab'+(R.length===1?'':'s')+' in '+SC.items.length+' image'+(SC.items.length===1?'':'s')+(SC.dupes?' · '+SC.dupes+' duplicate sighting'+(SC.dupes>1?'s':'')+' merged':'')+(low?' · <span style="color:var(--warn)">'+low+' need a quick check</span>':'')+'. Fix any cert or grade, then add.</p>'+
  '<div class="tablewrap"><table id="scanTable"><thead><tr><th class="nosort">Add</th><th class="nosort">Photo</th><th>Card</th><th>Grader</th><th>Cert #</th><th>Grade</th><th>Confidence</th><th class="n">Value</th><th>Purchase price</th><th class="nosort"></th></tr></thead><tbody>'+(rows||'<tr><td colspan="10" class="mut">Nothing left to add.</td></tr>')+'</tbody></table></div>'+
  '<div class="row" style="margin-top:12px"><label class="f" style="margin:0">Purchase date (for prices entered)</label><input type="date" id="scanDate" max="'+TODAY+'" value="'+SC.date+'"><span class="sp"></span><label class="row sm" style="gap:8px"><span class="toggle"><input type="checkbox" id="scanPriv"'+(SC.priv?' checked':'')+'><span></span></span>Keep purchase prices private</label></div>'+
  '<div class="row" style="margin-top:12px"><button class="btn ghost" data-act="scanBack">‹ Scan more</button><span class="sp"></span><button class="btn pri" data-act="scanAdd"'+(inc?'':' disabled')+'>Add '+inc+' slab'+(inc===1?'':'s')+' to showcase</button></div>'+
  '<p class="note">Demo matches are sample data. A real build reads the label text (grader, cert #) and confirms each cert with the grader before adding.</p>'}
var scanRendering=false;function scanRender(keepScroll){if(scanRendering)return;scanRendering=true;try{scanRender0(keepScroll)}finally{scanRendering=false}}
function scanRender0(keepScroll){var sh=$('#modal .sheet'),y=sh?sh.scrollTop:0;modal(SC.results?scanStep2():scanStep1(),true);if(keepScroll)$('#modal .sheet').scrollTop=y}
function addThumbs(){if(SC.results||$('#modal').hidden)return;scanRender(true)}
function extractFrames(file,onProg){return new Promise(function(res){var v=document.createElement('video'),frames=[],times=[],idx=0,done=false;function fin(){if(done)return;done=true;URL.revokeObjectURL(v.src);res(frames)}
  v.muted=true;v.playsInline=true;v.preload='auto';v.setAttribute('playsinline','');
  v.onloadedmetadata=function(){var d=isFinite(v.duration)&&v.duration>0?v.duration:1,n=Math.min(12,Math.max(3,Math.round(d*2)));for(var i=0;i<n;i++)times.push(d*(i+.5)/n);next()};
  function next(){if(idx>=times.length)return fin();v.currentTime=times[idx]}
  v.onseeked=function(){try{var w=240,h=Math.round(w*(v.videoHeight||320)/(v.videoWidth||240)),c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(v,0,0,w,h);frames.push({t:times[idx],thumb:c.toDataURL('image/jpeg',.72)})}catch(e){}onProg(idx+1,times.length);idx++;next()};
  v.onerror=fin;setTimeout(fin,20000);v.src=URL.createObjectURL(file)})}
function scanFiles(files){files=[].slice.call(files||[]);if(!files.length)return;var vids=files.filter(function(f){return /^video\//.test(f.type)}),imgs=files.filter(function(f){return /^image\//.test(f.type)});
  imgs.forEach(function(f){SC.items.push({kind:'image',name:f.name,thumb:URL.createObjectURL(f),key:f.name+f.size})});addThumbs();
  var chain=Promise.resolve();vids.forEach(function(f){chain=chain.then(function(){SC.busy='Extracting frames from '+f.name+'…';addThumbs();return extractFrames(f,function(a,b){SC.busy='Extracting frames from '+f.name+' — '+a+'/'+b;var el=$('#scanBusy');if(el)el.innerHTML='<span class="spinner"></span> '+esc(SC.busy)}).then(function(fr){if(!fr.length)toast('Couldn’t read that video in this browser');fr.forEach(function(x,i){SC.items.push({kind:'frame',name:f.name,label:f.name.slice(0,14)+' '+Math.floor(x.t/60)+':'+('0'+Math.floor(x.t%60)).slice(-2),thumb:x.thumb,key:f.name+f.size,vid:f.name+f.size,fi:i})})})})});
  chain.then(function(){SC.busy='';addThumbs()})}
function detect(){var dets=[],GRS=['PSA','PSA','PSA','BGS','SGC','CGC','CSG'];var pools={};
  SC.items.forEach(function(it,k){var r=rng(it.key+'|'+(it.fi==null?k:''));
    if(it.kind==='frame'){var pool=pools[it.vid]||(pools[it.vid]=(function(){var pr=rng(it.vid),n=3+Math.floor(pr()*4),a=[];for(var j=0;j<n;j++)a.push({g:GRS[Math.floor(pr()*GRS.length)],cert:String(10000000+Math.floor(pr()*89999999))});return a})());
      var nf=SC.items.filter(function(x){return x.vid===it.vid}).length,pos=Math.floor(it.fi*pool.length/nf);[pos,pos+1].forEach(function(p,q){if(p<pool.length&&(q===0||r()<.6))dets.push({g:pool[p].g,cert:pool[p].cert,thumb:it.thumb,conf:.7+r()*.29})})}
    else{var n=1+Math.floor(r()*3);for(var j=0;j<n;j++)dets.push({g:GRS[Math.floor(r()*GRS.length)],cert:String(10000000+Math.floor(r()*89999999)),thumb:it.thumb,conf:.7+r()*.29})}});
  var map={},out=[],dup=0;dets.forEach(function(d){var k=d.g+d.cert;if(map[k]){map[k].seen++;map[k].conf=Math.max(map[k].conf,d.conf);dup++;return}var c=fakeLookup(d.g,d.cert,SC.cat);var e={card:c,thumb:d.thumb,conf:d.conf,seen:1,inc:true,cost:'',dupe:false};map[k]=e;out.push(e)});
  out.forEach(function(e){if(S.mine.some(function(m){return m.cert===e.card.cert&&m.grader===e.card.grader})){e.dupe=true;e.inc=false}});
  SC.dupes=dup;return out}
A.scanOpen=function(d,e,ev){if(ev)ev.preventDefault();scanOpen()};
A.scanClear=function(){SC.items=[];scanRender()};
A.scanRead=function(d,b){b.disabled=true;var th=$('#scanThumbs');if(th)th.classList.add('scanning');var steps=['Finding slabs in each image…','Reading label text…','Matching certs…','Removing duplicates…'],i=0;var tick=setInterval(function(){b.innerHTML='<span class="spinner"></span> '+steps[Math.min(i,3)];i++},450);
  setTimeout(function(){clearInterval(tick);SC.results=detect();scanRender()},1900)};
A.scanBack=function(){SC.results=null;scanRender()};
A.scanRemove=function(d){SC.results.splice(+d.i,1);scanRender(true)};
A.scanAdd=function(){var add=SC.results.filter(function(r){return r.inc});SC.date=($('#scanDate')||{}).value||SC.date;SC.priv=$('#scanPriv').checked;
  add.slice().reverse().forEach(function(r){var c=r.card;var v=parseFloat(r.cost);if(!isNaN(v)&&v>=0){c.cost=v;c.costDate=SC.date}else{c.cost=null;c.costDate=null}c.hideCost=SC.priv;c.mode='none';S.mine.unshift(c)});
  save();closeModal();toast('Added '+add.length+' slab'+(add.length===1?'':'s')+' to your showcase ✓');SC=null;if(!/^#\/portfolio/.test(location.hash))location.hash='#/portfolio';else render(true)};
function scanEdit(t){var i=+t.dataset.i,r=SC.results[i],f=t.dataset.scan,td=t.closest('td');
  if(f==='inc'){r.inc=t.checked;var b=$('[data-act=scanAdd]'),n=SC.results.filter(function(x){return x.inc}).length;if(b){b.disabled=!n;b.textContent='Add '+n+' slab'+(n===1?'':'s')+' to showcase'}return}
  if(f==='cost'){r.cost=t.value;if(td)td.dataset.v=t.value;return}
  if(f==='grade'){r.card.grade=t.value;r.conf=1;setTimeout(function(){scanRender(true)},0);return}
  if(f==='grader'||f==='cert'){var g=f==='grader'?t.value:r.card.grader,cert=f==='cert'?t.value.trim():r.card.cert;if(!/^\d{7,10}$/.test(cert)){toast('Cert numbers are 7–10 digits');return}var nc=fakeLookup(g,cert);nc.id=r.card.id;r.card=nc;r.conf=1;r.dupe=S.mine.some(function(m){return m.cert===cert&&m.grader===g});toast('Re-checked '+g+' '+cert);setTimeout(function(){scanRender(true)},0)}}
