 function zoom(f,cx,cy){var r=stg.getBoundingClientRect();cx=cx==null?r.width/2:cx-r.left;cy=cy==null?r.height/2:cy-r.top;var ns=Math.max(1,Math.min(8,sc*f));var dx=cx-r.width/2,dy=cy-r.height/2;x=dx-(dx-x)*ns/sc;y=dy-(dy-y)*ns/sc;sc=ns;if(sc===1)x=y=0;ap()}
 function close(){o.remove();document.body.style.overflow='';document.removeEventListener('keydown',kd)}
