 o.addEventListener('click',function(e){var z=e.target.dataset&&e.target.dataset.z;if(z==='x'||e.target===o)close();else if(z==='+')zoom(1.5);else if(z==='-')zoom(1/1.5);else if(z==='0'){sc=1;x=y=0;ap()}else if(z==='n')show(i+1);else if(z==='p')show(i-1)});
 stg.addEventListener('wheel',function(e){e.preventDefault();zoom(e.deltaY<0?1.2:1/1.2,e.clientX,e.clientY)},{passive:false});
 var drag=null;stg.addEventListener('mousedown',function(e){drag={x:e.clientX-x,y:e.clientY-y,m:0};e.preventDefault()});
