/* ---------- Import purchase prices ---------- */
var IMP_SRC=['eBay','Fanatics Collect','Goldin','PWCC','COMC'];
function importPanel(){var q=(S.importQ||[]).length;return '<div class="panel imp" style="margin-top:14px"><div class="row"><h3 style="margin:0">💲 Import purchase prices</h3><span class="sp"></span><span class="lock sm">🔒 Paid prices stay private</span></div><p class="sm mut" style="margin:6px 0 10px">Pull what you paid from marketplaces or an order-history CSV. Matches by cert #, then player / year / set / grade, and fills paid price + purchase date.</p><div class="imp-b">'+
 IMP_SRC.map(function(s){return '<button class="btn sm" data-act="impLink" data-s="'+s+'">🔗 Link '+s+' <span class="demo-tag">demo</span></button>'}).join('')+
 '<label class="btn sm pri" style="cursor:pointer">⬆ Upload order history CSV<input type="file" accept=".csv,text/csv" hidden onchange="impCsv(this)"></label><button class="btn sm" data-act="impFwd">✉ Forward receipts</button><button class="btn sm ghost" data-act="impSample">⬇ Sample CSV</button></div>'+
 (q?'<button class="btn sm blue" style="margin-top:10px" data-act="impReview">Review '+q+' unmatched row'+(q>1?'s':'')+' ›</button>':'')+'</div>'}
A.impLink=function(d){modal('<h2 style="margin-top:0">Link '+esc(d.s)+' <span class="demo-tag">DEMO</span></h2><p class="sub">This is a demo connect flow — no real login happens and nothing is sent to '+esc(d.s)+'. In production you’d sign in with '+esc(d.s)+' (OAuth) and we’d read only your purchase history.</p><button class="btn pri block" data-act="impDemoRun" data-s="'+esc(d.s)+'">Simulate import from '+esc(d.s)+'</button>')};
A.impDemoRun=function(d){var rows=S.mine.filter(function(c){return c.real}).slice(0,3).map(function(c,i){return {date:dAdd(c.costDate||TODAY,0),title:c.set+' '+c.player+' '+cleanNum(c)+' '+c.grader+' '+c.grade,total:String(c.cost!=null?c.cost:50),cert:c.cert}});rows.push({date:'2025-03-14',title:'2021 Panini Prizm Mystery Card PSA 9',total:'45.00',cert:''});runImport(rows,d.s+' (demo)')};
A.impFwd=function(){modal('<h2 style="margin-top:0">Forward receipts <span class="demo-tag">DEMO</span></h2><p class="sub">Forward order confirmation emails to your private import address. We read the date, item title, total and cert #.</p><div class="panel row"><b class="sp" style="word-break:break-all">receipts+yo7k2@import.cardtradz.demo</b><button class="btn sm" onclick="navigator.clipboard&&navigator.clipboard.writeText(\'receipts+yo7k2@import.cardtradz.demo\');this.textContent=\'Copied\'">Copy</button></div><p class="sm mut">Demo address — mail sent here goes nowhere.</p>')};
A.impSample=function(){var L=['Order Date,Item Title,Total,Cert #'];S.mine.filter(function(c){return c.real}).slice(0,4).forEach(function(c,i){L.push([c.costDate||TODAY,'"'+c.set+' '+c.player+' '+cleanNum(c)+' '+c.grader+' '+c.grade+'"',(c.cost||50).toFixed(2),i<2?c.cert:''].join(','))});L.push('2025-02-02,"2019 Topps Chrome Unknown Player #99 PSA 8",24.99,');var a=document.createElement('a');a.href='data:text/csv;charset=utf-8,'+encodeURIComponent(L.join('\n'));a.download='cardtradz_sample_orders.csv';document.body.appendChild(a);a.click();a.remove();toast('Sample CSV downloaded')};
function csvParse(t){var R=[],r=[],f='',q=0;for(var i=0;i<t.length;i++){var ch=t[i];if(q){if(ch==='"'){if(t[i+1]==='"'){f+='"';i++}else q=0}else f+=ch}else if(ch==='"')q=1;else if(ch===','){r.push(f);f=''}else if(ch==='\n'||ch==='\r'){if(ch==='\r'&&t[i+1]==='\n')i++;r.push(f);f='';if(r.some(function(x){return x.trim()}))R.push(r);r=[]}else f+=ch}r.push(f);if(r.some(function(x){return x.trim()}))R.push(r);return R}
function hdrIdx(h,res){for(var i=0;i<h.length;i++){var k=h[i].toLowerCase().replace(/[^a-z#]/g,'');for(var j=0;j<res.length;j++)if(res[j].test(k))return i}return -1}
window.impCsv=function(inp){var f=inp.files[0];if(!f)return;var r=new FileReader();r.onload=function(){var R=csvParse(String(r.result));if(R.length<2){toast('No rows found');return}var h=R[0],iD=hdrIdx(h,[/^(order|purchase|sold|sale|transaction)?date/,/date/]),iT=hdrIdx(h,[/^(item)?(title|name|description)/,/item|title|desc|card/]),iP=hdrIdx(h,[/^(total|ordertotal|grandtotal)/,/total|price|amount|paid|cost/]),iC=hdrIdx(h,[/cert/,/serial|psa#/]);
 if(iP<0){toast('Couldn’t find a price/total column');return}
 runImport(R.slice(1).map(function(x){return {date:iD>=0?x[iD]:'',title:iT>=0?x[iT]:'',total:x[iP],cert:iC>=0?x[iC]:''}}),f.name)};r.readAsText(f);inp.value=''};
function normDate(s){s=(s||'').trim();var m=s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);if(m)return m[1]+'-'+('0'+m[2]).slice(-2)+'-'+('0'+m[3]).slice(-2);m=s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})/);if(m){var y=m[3].length===2?'20'+m[3]:m[3];return y+'-'+('0'+m[1]).slice(-2)+'-'+('0'+m[2]).slice(-2)}var t=Date.parse(s);return isNaN(t)?TODAY:new Date(t).toISOString().slice(0,10)}
function matchCard(r){var cert=(r.cert||'').replace(/\D/g,'');if(cert){var c=S.mine.filter(function(x){return String(x.cert)===cert})[0];if(c)return c}var t=' '+(r.title||'').toLowerCase()+' ',best=null,bs=0;
 S.mine.forEach(function(c){var last=(c.player||'').toLowerCase().split(' ').pop();if(!last||t.indexOf(last)<0)return;var sc=2,yr=(c.set||'').match(/(19|20)\d\d/);if(yr&&t.indexOf(yr[0])>=0)sc++;else if(yr&&/(19|20)\d\d/.test(t))return;
  if(new RegExp('(psa|bgs|sgc|cgc)\\s*'+String(c.grade).replace('.','\\.')+'(\\D|$)').test(t))sc+=2;else if(/(psa|bgs|sgc|cgc)\s*\d/.test(t))return;
  (c.set||'').toLowerCase().replace(/(19|20)\d\d/,'').split(/\s+/).forEach(function(w){if(w.length>3&&t.indexOf(w)>=0)sc+=.5});var n=String(c.num||'').replace('#','');if(n&&t.indexOf('#'+n.toLowerCase())>=0)sc++;if(sc>bs){bs=sc;best=c}});return bs>=4?best:null}
function runImport(rows,src){var ok=0,q=S.importQ=S.importQ||[];rows.forEach(function(r){var p=parseFloat(String(r.total||'').replace(/[^0-9.\-]/g,''));if(isNaN(p))return;var d=normDate(r.date),c=matchCard(r);if(c){c.cost=Math.round(p*100)/100;c.costDate=d;c.hideCost=true;c.demoCost=false;ok++}else q.push({id:uid('Q'),date:d,title:r.title||'(no title)',price:p,cert:(r.cert||'').trim(),src:src})});save();closeModal();toast('Imported '+ok+' price'+(ok===1?'':'s')+(q.length?' · '+q.length+' to review':''));render(true);if(q.length)A.impReview()}
A.impReview=function(){var q=S.importQ||[];if(!q.length){closeModal();return}modal('<h2 style="margin-top:0">Review unmatched rows</h2><p class="sub">Assign each purchase to one of your slabs, edit if needed, then confirm. 🔒 Private.</p>'+q.map(function(r){return '<div class="panel imp-q" data-q="'+r.id+'"><div class="sm"><b>'+esc(r.title)+'</b>'+(r.cert?' · cert '+esc(r.cert):'')+' <span class="mut">· '+esc(r.src)+'</span></div><div class="row wrap" style="gap:8px;margin-top:8px"><select class="sp" id="qc_'+r.id+'"><option value="">Assign to card…</option>'+S.mine.map(function(c){return '<option value="'+c.id+'">'+esc(c.player+' · '+c.set+' '+cleanNum(c)+' · '+c.grader+' '+c.grade)+'</option>'}).join('')+'</select><input id="qp_'+r.id+'" type="number" step="0.01" value="'+r.price+'" style="width:100px"><input id="qd_'+r.id+'" type="date" value="'+r.date+'" style="width:150px"><button class="btn sm pri" data-act="impOk" data-q="'+r.id+'">Confirm</button><button class="btn sm bad" data-act="impDrop" data-q="'+r.id+'" aria-label="Dismiss">✕</button></div></div>'}).join(''),true)};
A.impOk=function(d){var c=card($('#qc_'+d.q).value);if(!c){toast('Pick a card first');return}c.cost=Math.round(parseFloat($('#qp_'+d.q).value)*100)/100;c.costDate=$('#qd_'+d.q).value||TODAY;c.hideCost=true;c.demoCost=false;S.importQ=S.importQ.filter(function(r){return r.id!==d.q});save();toast('Saved paid price for '+c.player);render(true);A.impReview()};
A.impDrop=function(d){S.importQ=S.importQ.filter(function(r){return r.id!==d.q});save();render(true);A.impReview()};
